from pwn import xor

def xor_decrypt(data, single_byte_key):
    return xor(data, single_byte_key)

def main():
    with open('/home/ctfplayer/ctf_files/decoded_binary.bin', 'rb') as f:
        ciphertext = f.read()

    for key in range(256):
        plaintext_candidate = xor_decrypt(ciphertext, key)
        if b'flag{' in plaintext_candidate:
            print(f"Key: {key}\n{plaintext_candidate.decode('utf-8')}")
            return

if __name__ == "__main__":
    main()
